using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using Microsoft.Win32;
class StartupQuotaTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static CodexQuotaSnapshot Snapshot(DateTime now,double remaining,DateTime reset,string account="account-A"){return new CodexQuotaSnapshot{CheckedUtc=now,AccountKey=account,Windows=new List<CodexQuotaWindow>{new CodexQuotaWindow{Minutes=10080,Remaining=remaining,ResetUtc=reset}}};}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);string key=@"Software\ConanAssistantTests\"+Guid.NewGuid().ToString("N");try{
 var now=new DateTime(2026,10,22,9,0,0,DateTimeKind.Utc);var cfg=new CodexQuotaConfig();var reader=new CodexQuotaReader();var baseline=Snapshot(now,30,now.AddDays(2));Check(reader.ObserveResets(baseline,cfg,now).Length==0,"first observation establishes baseline");var refill=Snapshot(now.AddMinutes(1),100,now.AddDays(2));var events=reader.ObserveResets(refill,cfg,refill.CheckedUtc);Check(events.Length==1&&events[0].Kind=="early"&&events[0].Minutes==10080,"early weekly refill recorded as suspected reset");Check(events[0].ObservedUtc==refill.CheckedUtc&&events[0].PreviousCheckedUtc==now,"detection time and previous observation retained");Check(reader.ObserveResets(refill,cfg,refill.CheckedUtc).Length==0,"cached sample cannot duplicate reset");var restart=new JavaScriptSerializer().Deserialize<CodexQuotaConfig>(new JavaScriptSerializer().Serialize(cfg));Check(new CodexQuotaReader().ObserveResets(refill,restart,refill.CheckedUtc).Length==0&&restart.ResetHistory.Count==1,"history and baseline survive restart");var switchAccount=Snapshot(now.AddMinutes(2),100,now.AddDays(3),"account-B");Check(reader.ObserveResets(switchAccount,cfg,switchAccount.CheckedUtc).Length==0,"account switch never reports reset");var unknown=new CodexQuotaConfig{LastObserved=Snapshot(now,20,now.AddDays(2),"")};Check(reader.ObserveResets(Snapshot(now.AddSeconds(1),100,now.AddDays(2),""),unknown,now.AddSeconds(1)).Length==0,"unknown identity does not infer reset");var normal=new CodexQuotaConfig{LastObserved=Snapshot(now.AddMinutes(-2),5,now.AddMinutes(-1))};events=reader.ObserveResets(Snapshot(now,94,now.AddDays(7)),normal,now);Check(events.Length==1&&events[0].Kind=="scheduled","new weekly cycle recorded after old deadline");var small=new CodexQuotaConfig{LastObserved=baseline};Check(reader.ObserveResets(Snapshot(now.AddMinutes(1),31,now.AddDays(2)),small,now.AddMinutes(1)).Length==0,"minor quota adjustment not called reset");Check(reader.ObserveResets(Snapshot(now.AddMinutes(-8),100,now.AddDays(2)),new CodexQuotaConfig(),now).Length==0,"stale samples cannot create reset records");var q=Snapshot(now,40,now.AddMinutes(5));cfg=new CodexQuotaConfig();Check(reader.ResetReminders(q,cfg,now).Length==1,"reset lead reminder fires at chosen five minutes");Check(reader.ResetReminders(q,cfg,now.AddSeconds(1)).Length==0,"reset reminder deduplicated");restart=new JavaScriptSerializer().Deserialize<CodexQuotaConfig>(new JavaScriptSerializer().Serialize(cfg));Check(new CodexQuotaReader().ResetReminders(q,restart,now.AddSeconds(2)).Length==0,"reminder dedup survives restart");Check(reader.ResetReminders(q,new CodexQuotaConfig{ResetReminder=false},now).Length==0,"manual reset reminder switch respected");Check(reader.ResetReminders(q,new CodexQuotaConfig(),now.AddMinutes(6)).Length==0,"expired window does not announce unconfirmed reset");Check(CodexQuotaReader.Countdown(q,10080,now)=="00:05:00"&&CodexQuotaReader.Countdown(q,10080,now.AddSeconds(1))=="00:04:59","countdown changes every second");Check(CodexQuotaReader.Countdown(q,10080,now.AddMinutes(5)).Contains("等待官方"),"countdown expiry waits for official confirmation");var id=CodexQuotaReader.AccountFingerprint(new Dictionary<string,object>{{"account",new Dictionary<string,object>{{"email","test@example.invalid"}}}});Check(id.Length==64&&!id.Contains("@"),"account matching stores hash only");
 string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ConanPet.exe");File.Copy(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,exe,true);var startup=new StartupIntegration(exe,key,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-desktop"));Check(!startup.Enabled,"startup default remains off");startup.SetEnabled(true);Check(startup.CurrentVersion&&startup.RegisteredCommand=="\""+exe+"\"","startup command quotes paths with spaces");using(var r=Registry.CurrentUser.OpenSubKey(key,true))r.SetValue("Unrelated","keep");startup.SetEnabled(false);using(var r=Registry.CurrentUser.OpenSubKey(key))Check(!startup.Enabled&&Convert.ToString(r.GetValue("Unrelated"))=="keep","disabling removes only owned startup value");startup.CreateShortcut();Check(File.Exists(startup.ShortcutPath),"desktop shortcut created in isolated folder");startup.CreateShortcut();Check(File.Exists(startup.ShortcutPath),"owned shortcut can be safely updated");object host=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object link=host.GetType().InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,host,new object[]{startup.ShortcutPath});var target=Convert.ToString(link.GetType().InvokeMember("TargetPath",System.Reflection.BindingFlags.GetProperty,null,link,null));Check(String.Equals(target,exe,StringComparison.OrdinalIgnoreCase),"shortcut target matches current executable");link.GetType().InvokeMember("Description",System.Reflection.BindingFlags.SetProperty,null,link,new object[]{"Unrelated shortcut"});link.GetType().InvokeMember("Save",System.Reflection.BindingFlags.InvokeMethod,null,link,null);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(host);bool refused=false;try{startup.CreateShortcut();}catch(IOException){refused=true;}Check(refused,"unrelated same-name shortcut never overwritten");
 if(args.Contains("--live")){var live=CodexQuotaReader.Fetch("");Check(live.Windows.Count>0&&live.AccountKey.Length==64,"official account and quota handshake works without identity logging");}
 }catch(Exception e){failures++;Console.WriteLine(e.GetType().Name+" "+e.Message);}finally{Registry.CurrentUser.DeleteSubKeyTree(key,false);}File.WriteAllText(Path.Combine(args[0],"startup-quota-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,real_startup_changed=false,real_desktop_changed=false}));return failures==0?0:1;}
}
